package org.transittr;
import java.io.*;import java.util.*;import org.json.*;
/** ATUS mobile stop predictions plus observed vehicle positions; never estimates GPS from stops. */
public final class KonyaClient {
 private static final String BASE="https://atus-api.konya.bel.tr/api/AtusService/",TI="zva@HqF%@ekH4IztvSvXK";
 private static final LinkedHashMap<String,JSONObject> cache=new LinkedHashMap<String,JSONObject>();
 private static final HashMap<String,Long> times=new HashMap<String,Long>();
 public static JSONObject get(String method,JSONObject body)throws IOException{try{body.put("ti",TI);JSONObject root=new JSONObject(ApiHttp.json(BASE+method,body));if(!root.optBoolean("Status",false))throw new IOException("ATUS mobil servisi hata verdi");return root;}catch(JSONException e){throw new IOException("ATUS yanıtı okunamadı");}}
 public static boolean matches(String line,String filter){if(filter.length()==0||line.equalsIgnoreCase(filter))return true;String[] pieces=filter.split("-");return (pieces.length==1||!pieces[1].matches("[0-9]+"))&&line.split("-")[0].equalsIgnoreCase(pieces[0]);}
 private static synchronized JSONObject vehicle(String id)throws IOException{Long time=times.get(id);if(time!=null&&System.currentTimeMillis()-time.longValue()<15000)return cache.get(id);try{JSONObject body=new JSONObject();body.put("aracNo",id);JSONArray rows=get("getAracBilgi",body).getJSONArray("Data");JSONObject result=rows.length()>0?rows.getJSONObject(0):new JSONObject();cache.put(id,result);times.put(id,Long.valueOf(System.currentTimeMillis()));while(cache.size()>32){String first=cache.keySet().iterator().next();cache.remove(first);times.remove(first);}return result;}catch(JSONException e){throw new IOException("ATUS araç konumu okunamadı");}}
 public static JourneyData.Snapshot query(String stop,String filter,boolean gps)throws IOException{try{JSONObject body=new JSONObject();body.put("durakNo",stop);JourneyData.Snapshot s=parse(get("atusTahmin",body).getJSONArray("Data"),stop,filter);int fetched=0,failed=0;HashSet<String> done=new HashSet<String>();if(gps)for(JourneyData.Vehicle v:s.rows){if(!v.id.startsWith("atus:")||done.contains(v.id)||fetched>=12)continue;done.add(v.id);fetched++;try{JSONObject p=vehicle(v.id.substring(5));applyPosition(v,p);}catch(IOException e){failed++;}}if(failed>0)s.message="Bazı araçların GPS konumu alınamadı; varış süreleri gösteriliyor.";else if(gps&&s.rows.size()>12)s.message="Haritada ilk 12 aracın kaynak konumu; tüm varışlar aşağıda listelenir.";return s;}catch(JSONException e){throw new IOException("ATUS durak tahminleri okunamadı");}}
 public static void applyPosition(JourneyData.Vehicle v,JSONObject p){v.lat=SourceTools.number(p,"SON_ENLEM");v.lon=SourceTools.number(p,"SON_BOYLAM");v.sourceTime=p.optString("TARIHSAAT",p.optString("UpdateTarihSaat",""));v.observedAt=SourceTools.time(v.sourceTime);v.closestStop=p.optString("SIMDIKI_DURAK","");}
 public static JourneyData.Snapshot parse(JSONArray rows,String stop,String filter)throws JSONException,IOException{if(rows.length()>200)throw new IOException("ATUS sonuç sınırı");JourneyData.Snapshot s=new JourneyData.Snapshot();s.source="Konya ATUS Mobil · varış + araç GPS";
  for(int i=0;i<rows.length();i++){JSONObject r=rows.getJSONObject(i);String line=r.optString("HAT_NO","");if(!matches(line,filter))continue;String id=SourceTools.text(r,"ARAC_NO"),eta=SourceTools.text(r,"TAHMINI_SURE");if(!id.matches("[0-9]+")||eta.length()==0||eta.toUpperCase(new Locale("tr","TR")).indexOf("ARAÇ YOK")>=0)continue;JourneyData.Vehicle v=new JourneyData.Vehicle();v.id="atus:"+id;v.line=line;v.name=r.optString("HAT_ADI","")+" · "+r.optString("YON","");v.eta=eta;java.util.regex.Matcher m=java.util.regex.Pattern.compile("^([0-9]+)\\s*dk",2).matcher(eta);if(m.find())v.etaSeconds=Long.parseLong(m.group(1))*60;else if(eta.toUpperCase(new Locale("tr","TR")).indexOf("DURAKTA")>=0)v.etaSeconds=0;v.arrivalStop=stop;v.etaIsStopArrival=v.etaSeconds>=0;s.rows.add(v);}
  SourceTools.sort(s);if(s.rows.isEmpty())s.message="Bu durak ve hat için yaklaşan araç yok.";return s;
 }
}
